        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nPancetta\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook spaghetti in salted water\n2. Fry pancetta until crispy\n3. Whisk eggs with grated cheese and pepper\n4. Toss hot pasta with pancetta\n5. Remove from heat and stir in egg mixture\n6. Serve immediately with extra cheese", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTomato sauce\nHeavy cream\nOnion\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or broil chicken until charred\n3. Sauté onion, garlic, and ginger\n4. Add tomato sauce and simmer\n5. Stir in cream and garam masala\n6. Add chicken pieces and simmer 10 minutes\n7. Serve with basmati rice", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nTofu\nBean sprouts\nPeanuts\nLime\nTamarind paste\nFish sauce\nEggs", Steps = "1. Soak rice noodles in warm water\n2. Make sauce: tamarind, fish sauce, sugar\n3. Fry tofu until golden\n4. Scramble eggs in the wok\n5. Add noodles and sauce, toss\n6. Add bean sprouts\n7. Serve with peanuts and lime", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm tortillas\n5. Assemble tacos with toppings\n6. Serve with salsa and sour cream", AverageRating = 4.2, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste\nCoconut milk\nChicken breast\nBamboo shoots\nThai basil\nFish sauce\nPalm sugar", Steps = "1. Heat coconut cream until oil separates\n2. Fry curry paste until fragrant\n3. Add chicken and cook through\n4. Pour in remaining coconut milk\n5. Add bamboo shoots, fish sauce, sugar\n6. Simmer 10 minutes\n7. Stir in Thai basil", AverageRating = 4.6, RatingCount = 11 },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until fluffy\n3. Fold in chocolate mixture\n4. Add flour and vanilla\n5. Pour into greased ramekins\n6. Bake at 425°F for 12 minutes\n7. Invert onto plates and serve immediately", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 8, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Dice onion, tomato, jalapeño\n4. Mix everything together\n5. Add lime juice and salt\n6. Stir in chopped cilantro\n7. Serve with tortilla chips", AverageRating = 4.4, RatingCount = 18 },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe == null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var allRatings = _ratings[recipeId];
        recipe.AverageRating = Math.Round(allRatings.Average(), 1);
        recipe.RatingCount = recipe.RatingCount + 1;
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}
